SELECT public.qa_run_v403('aaaaaaaa-aaaa-4aaa-8aaa-000000000002');
SELECT public.qa_batch_v403('aaaaaaaa-aaaa-4aaa-8aaa-000000000002',jsonb_build_array(public.qa_record_v403('transaction','t1'),public.qa_record_v403('investment','component-a',300),public.qa_record_v403('investment','component-b',700),public.qa_record_v403('balance','bank',500)));
SELECT public.qa_assert_v403('unchanged transaction is not rewritten',(SELECT count(*)=3 FROM public.lts_open_finance_observation WHERE sync_run_id='aaaaaaaa-aaaa-4aaa-8aaa-000000000002'));
SELECT public.qa_finish_v403('aaaaaaaa-aaaa-4aaa-8aaa-000000000002',4);
SELECT public.qa_assert_v403('received coverage remains four',(SELECT raw_count=4 AND normalized_count=4 AND metadata#>>'{ingestion_v403,unchanged_not_repeated}'='1' FROM public.lts_open_finance_sync_run WHERE id='aaaaaaaa-aaaa-4aaa-8aaa-000000000002'));
SELECT public.qa_assert_v403('both unchanged CDBs retained in same completed cohort',(SELECT count(*)=2 FROM public.lts_open_finance_observation WHERE sync_run_id='aaaaaaaa-aaaa-4aaa-8aaa-000000000002'AND resource_type='investment'));
SELECT public.qa_assert_v403('staging consultation clock is updated',(SELECT sync_run_id='aaaaaaaa-aaaa-4aaa-8aaa-000000000002'FROM public.lts_open_finance_staging WHERE provider_record_id='synthetic-item:t1'));
SELECT public.qa_run_v403('aaaaaaaa-aaaa-4aaa-8aaa-000000000003');
