SELECT public.qa_batch_v403('aaaaaaaa-aaaa-4aaa-8aaa-000000000005',jsonb_build_array(jsonb_set(public.qa_record_v403('transaction','t1',11),'{reconciliation}','{"classification":"candidate"}')));
